def priority(item: float, remaining_capacity: float, bin_capacity: float) -> float:
    # If the item does not fit, make the bin unattractive.
    if remaining_capacity < item:
        return -float('inf')

    # Relative size of the item.
    r = item / bin_capacity

    # For large items use Best Fit (minimize leftover space).
    # For small items use Worst Fit (maximize leftover space) to reduce fragmentation.
    if r > 0.5:
        return -(remaining_capacity - item)   # Best Fit
    else:
        return remaining_capacity - item      # Worst Fit

def priority(item: float, remaining_capacity: float, bin_capacity: float) -> float:
    # If the item does not fit, return a very low priority.
    if remaining_capacity < item - 1e-12:
        return -float('inf')
    leftover = remaining_capacity - item
    # Normalized squared leftover penalizes large fragments more strongly.
    eps = 1e-9
    return -(leftover * leftover) / (remaining_capacity + eps)

