def priority(item: float, remaining_capacity: float, bin_capacity: float) -> float:
    # If the item does not fit, discourage this bin strongly
    if item > remaining_capacity:
        return float('-inf')
    leftover = remaining_capacity - item          # unused space after placement
    # Proportion of the bin already filled before placing the item
    used_ratio = (bin_capacity - remaining_capacity) / bin_capacity if bin_capacity != 0 else 0.0
    # Best Fit core (minimize leftover) with a small bias toward fuller bins
    return -leftover + 0.01 * used_ratio

