    leftover = remaining_capacity - item
    return -(leftover * leftover)

def priority(item: float, remaining_capacity: float, bin_capacity: float) -> float:
    # If the item does not fit, give the lowest possible priority.
    if remaining_capacity < item:
        return -float('inf')

    leftover = remaining_capacity - item          # unused space after placing the item
    # Give extra weight to bins that are already fuller;
    # this encourages filling existing bins before opening new ones.
    weight = remaining_capacity / bin_capacity if bin_capacity != 0 else 0.0
    # Higher priority (less negative) for smaller leftover * weight.
    return -leftover * weight
